const createResponseInstance = (
  body?: BodyInit | null | undefined,
  init?: globalThis.ResponseInit
): Response => new Response(body, init)

// `Set-Cookie` is the only multi-value header, so it must be merged, not set.
// The earlier cookies come first so the later, more specific ones can override them.
const mergeSetCookieHeaders = (headers: Headers, earlier: string[], later: string[]) => {
  headers.delete('set-cookie')
  for (const cookie of earlier) {
    headers.append('set-cookie', cookie)
  }
  for (const cookie of later) {
    headers.append('set-cookie', cookie)
  }
}

export class Context<
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  E extends Env = any,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  P extends string = any,
  I extends Input = {},
...
   * @param _res - The Response object to set.
   */
  set res(_res: Response | undefined) {
    if (this.#res && _res) {
      _res = createResponseInstance(_res.body, _res)
      for (const [k, v] of this.#res.headers.entries()) {
        // `set-cookie` is multi-value and is merged once, outside this loop
        if (k === 'content-type' || k === 'set-cookie') {
          continue
        }
        _res.headers.set(k, v)
      }
      const resCookies = _res.headers.getSetCookie()
      mergeSetCookieHeaders(_res.headers, this.#res.headers.getSetCookie(), resCookies)
    } else if (_res && this.#preparedHeaders && !this.finalized) {
      // `c.header()`/`setCookie()` calls made before a Response existed are kept
      // in `#preparedHeaders`. They may already have been copied into `_res` by
      // `c.newResponse()`, so only recover the cookies that are missing.
      const preparedCookies = this.#preparedHeaders.getSetCookie()
      if (preparedCookies.length) {
        _res = createResponseInstance(_res.body, _res)
        const resCookies = _res.headers.getSetCookie()
        const missingCookies = preparedCookies.filter((cookie) => !resCookies.includes(cookie))
        if (missingCookies.length) {
          mergeSetCookieHeaders(_res.headers, missingCookies, resCookies)
        }
      }
    }
    this.#res = _res
    this.finalized = true
  }

